-- Phase 4 seed data
-- Persian labels with broken word order from the source mockup were normalized using the source English meaning.

MERGE INTO CIF.REF_ECONOMIC_SECTOR T
USING (SELECT 'BANKING' AS ECONOMIC_SECTOR_CODE, 'بانکداری' AS NAME_FA, 'Banking' AS NAME_EN, NULL AS DESCRIPTION_FA, 10 AS SORT_ORDER, 1 AS IS_ACTIVE, NULL AS PARENT_CODE, NULL AS VALID_FROM, NULL AS VALID_TO, 1 AS RECORD_VERSION FROM DUAL) S
ON (T.ECONOMIC_SECTOR_CODE=S.ECONOMIC_SECTOR_CODE)
WHEN MATCHED THEN UPDATE SET T.NAME_FA=S.NAME_FA, T.NAME_EN=S.NAME_EN, T.DESCRIPTION_FA=S.DESCRIPTION_FA, T.SORT_ORDER=S.SORT_ORDER, T.IS_ACTIVE=S.IS_ACTIVE, T.PARENT_CODE=S.PARENT_CODE, T.VALID_FROM=S.VALID_FROM, T.VALID_TO=S.VALID_TO, T.RECORD_VERSION=S.RECORD_VERSION
WHEN NOT MATCHED THEN INSERT (ECONOMIC_SECTOR_CODE, NAME_FA, NAME_EN, DESCRIPTION_FA, SORT_ORDER, IS_ACTIVE, PARENT_CODE, VALID_FROM, VALID_TO, RECORD_VERSION)
VALUES (S.ECONOMIC_SECTOR_CODE, S.NAME_FA, S.NAME_EN, S.DESCRIPTION_FA, S.SORT_ORDER, S.IS_ACTIVE, S.PARENT_CODE, S.VALID_FROM, S.VALID_TO, S.RECORD_VERSION);

